insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values (E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c',E'Formato para la presentación de Propuestas de Información Geográfica de Interés Nacional',E'FIIN-GEO',null,null,true,ARRAY[E'SNIEG',E'INEGI',E'Información de Interés Nacional',E'Propuestas geográficas',E'Formato',E'Instructivo']::text[],E'https://www.snieg.mx/Documentos/Normatividad/Formatos_reg/Formato_IIN_Geografica.pdf',E'formato') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'8e66f7a0-0cbc-53fa-9a3c-4eb9bf49ded1',E'Marco legal, conceptos y proponente · pág. 2',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">       FORMATO PARA LA PRESENTACIÓN DE PROPUESTAS DE INFORMACIÓN GEOGRÁFICA DE INTERÉS NACIONAL\n                                                  MARCO LEGAL\nCon fundamento en lo dispuesto por el apartado B del artículo 26 de la Constitución Política de los Estados Unidos Mexicanos y artículos 54;\n55 fracción I y II; 77 fracción II y; 78 de la Ley del Sistema Nacional de Información Estadística y Geográfica (LSNIEG) y, de conformidad con el\nArtículo 11 de las Reglas para la Determinación de Información de Interés Nacional, emitidas por el Instituto Nacional de Estadística y\nGeografía (Publicadas en el DOF 09-04-2018), se establece el presente formato para documentar la información geográfica a proponer\ncomo de Interés Nacional para el Sistema Nacional de Información Estadística y Geográfica.\n                                               CONCEPTOS BÁSICOS\nInformación propuesta: grupo de datos y productos derivados de ellos, definido mediante la especificación de temas, subtemas, universos,\ncobertura espacial y temporal, periodicidad, escalas, proyecciones, variables u objetos espaciales, clasificaciones y parámetros que sean\nresultado de un operativo estadístico o geográfico determinado y puesto a consideración de la Junta de Gobierno para ser valorado y, en\nsu caso, determinado como Información de Interés Nacional.\nGrupos de datos geográficos: marco de referencia geodésico; límites costeros, internacionales, estatales y municipales; datos de relieve\ncontinental, insular y submarino; datos catastrales, topográficos, de recursos naturales y clima, así como nombres geográficos.\nProponente: Unidad del Estado que presenta una propuesta de información para que sea determinada como de Interés Nacional de\nacuerdo con lo previsto en el artículo 78, de la LSNIEG.\nProyecto geográfico: conjunto de actividades ordenadas y relacionadas entre sí cuyo propósito consiste en producir, integrar, analizar y\ndifundir información geográfica que permita cuantificar y caracterizar un universo de estudio o aspecto específico.\n                                    1. INFORMACIÓN PROPUESTA Y PROPONENTE\n1.1 Nombre de la Unidad del Estado y del Comité Técnico\n   Especializado que propone la información para ser\n   designada como Información de Interés Nacional:\n1.2 Denominación de la información propuesta:\n   (Anote el nombre de la información geográfica propuesta)\n1.3 Objetivo de la información propuesta:</pre></div></section>',E'anexo',1,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Marco legal, conceptos y proponente',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'5ccf20f4-e20e-5204-9950-b32cc35f00c0',E'Grupos de datos, usuarios y proyecto geográfico · pág. 3',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">1.4 De los siguientes grupos de datos, marque las opciones que relacionen a la información propuesta como de Interés Nacional.\n   Si selecciona &quot;Otro&quot;, especifique el grupo:\n                                             (Marque las opciones correspondientes)\n                                                   Grupo de Datos\n 1 Marco de referencia geodésico\n 2 Límites costeros, internacionales, estatales y municipales\n 3 Datos de relieve continental, insular y submarino\n 4 Datos catastrales\n 5 Datos topográficos\n 6 Datos de recursos naturales y clima\n 7 Nombres geográficos\n 8 Otro:\n1.5 Principales usuarios identificados de la\n   información propuesta:\n               2. PROYECTO GEOGRÁFICO QUE GENERA LA INFORMACIÓN E INSTITUCIÓN RESPONSABLE\n2.1 Descripción del proyecto geográfico:\n2.2 Fases que comprende el proyecto geográfico:     2.3 Unidad responsable de efectuar las fases del proyecto geográfico:\n2.2.1 Diseño\n2.2.1.1\n2.2.1.2\n2.2.1.3\n2.2.1.4\n2.2.1.5</pre></div></section>',E'anexo',2,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Grupos de datos, usuarios y proyecto geográfico',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
