insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'38237467-6336-5f1a-9c30-f39ba61b4a86',E'Políticas públicas y fundamento legal · pág. 6',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                   3. POLÍTICAS PÚBLICAS DE ALCANCE NACIONAL\n3.1 La información geográfica propuesta se utiliza para:\n3.1.1 Diseñar nuevas\n     políticas públicas en\n     materia de:\n3.1.2 El seguimiento\n     de qué políticas\n     públicas:\n3.2 La información geográfica propuesta debe generarse porque lo estipula:\n3.2.1 Ley aplicable:\n     Si selecciona la opción &quot;Sí&quot;, anote: Nombre de la ley, título, capítulo, sección, artículo, fracción, párrafo, fecha de última publicación y observaciones.\n      Sí        No\n       Limpiar\n3.2.2 Otro ordenamiento jurídico:\n     Si selecciona la opción &quot;Sí&quot;, anote: Nombre del ordenamiento, especificaciones, fecha de última publicación y observaciones.\n     Sí       No\n      Limpiar</pre></div></section>',E'anexo',5,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Políticas públicas y fundamento legal',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
