insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'043cc4c1-6c26-5f0a-b622-e336449beb43',E'Atención de emergencias · pág. 9',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                         4. ATENCIÓN DE EMERGENCIAS O COMPROMISOS INTERNACIONALES\n4.1 ¿Cuáles de los siguientes organismos han declarado de utilidad la información propuesta para prevenir o atender desastres\n   naturales?\n   Marque las opciones correspondientes, si la opción es &quot;Ninguno&quot; pase a 4.3\n                           1. Sistema Nacional de Protección Civil\n                           2. Centro Nacional de Prevención de Desastres (CENAPRED)\n                           3. Otro\n                           4. Ninguno\n4.2 Anote la disposición y el lugar donde puede consultarse el fundamento donde se declare que la información propuesta se utiliza\n   para prevenir o atender desastres naturales:\n                      Disposición                                         Lugar donde puede consultarse</pre></div></section>',E'anexo',8,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Atención de emergencias',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'9f00bb73-55bd-5fab-b764-d46382e4d407',E'Compromisos internacionales · pág. 10',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">4.3 ¿La información propuesta se utiliza para atender acuerdos, tratados o compromisos establecidos a nivel internacional?\n   (Si selecciona la opción &quot;Sí&quot;, especifique el nombre de los acuerdos, tratados o compromisos y organismos o países; si selecciona la opción &quot;No&quot;, deje en blanco 4.4)\n    Sí         No\n4.4 ¿El compromiso internacional ha sido suscrito por el Presidente de la República y aprobado por el Senado?\n    (Si selecciona la opción &quot;Sí&quot;, anexar el documento que sustente el compromiso y anotar el nombre del mismo y las observaciones pertinentes en el recuadro)\n   Sí         No</pre></div></section>',E'anexo',9,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Compromisos internacionales',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'3f50fa71-182e-56fb-9216-09d355d5c49b',E'Cobertura, referencia temporal y objetos espaciales · pág. 11',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                      5. METODOLOGÍA PARA LA GENERACIÓN DE LA INFORMACIÓN PROPUESTA\n5.1 ¿Cuál es la cobertura geográfica de la información propuesta?\n5.2 ¿Cuál es la referencia temporal de la información propuesta conforme a las fases del proyecto geográfico?\n                              Fase                                    Referencia temporal\n5.3 Temas y objetos espaciales de la información propuesta:\n                             Tema                                       Objetos espaciales\n5.4 ¿Cuál es la unidad mínima de la información propuesta?</pre></div></section>',E'anexo',10,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Cobertura, referencia temporal y objetos espaciales',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'0f804d8b-abb1-5021-ac17-c165b12b3abb',E'Geodesia, proyección, escala y periodicidad · pág. 12',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.5 Para la información propuesta indique:\n        5.5.1 Marco de Referencia Geodésico\n        5.5.2 Proyección\n        5.5.3 Escala                      *Resolución                   Exactitud\n        * Aplica para información en formato ráster\n5.6 ¿La Unidad Responsable de la generación de la información propuesta cuenta con un fundamento legal que le permita decidir con\n    independencia sobre las metodologías y normas empleadas, al margen de influencias políticas y otras influencias externas?\n    Sí    No\n                Limpiar\n5.7 ¿Se dan a conocer a los usuarios de la información propuesta los metadatos, metodologías, así como las fechas de publicación de la\n   misma?\n             Metadatos                             Metodologías                         Fechas de publicación\n            Sí            No  Limpiar               Sí             No  Limpiar               Sí               No  Limpiar\n5.8 Indicar las acciones que se emplean para generar o actualizar la información propuesta de manera regular:\n5.9 ¿Cuál es la periodicidad con la que se genera o actualiza la información propuesta?\n                              Fase                                         Frecuencia\n5.10 Indique la frecuencia con la que se hace pública la información propuesta:\n    Marque la opción correspondiente (sólo una)\n                                      1. Mensual\n                                      2. Anual\n                                      3. Bienal\n                                      4. Trianual\n                                      5. Quinquenal\n                                      6. Otra</pre></div></section>',E'anexo',11,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Geodesia, proyección, escala y periodicidad',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'943fdf14-ab99-56fe-bdf7-3327a7f8d891',E'Disponibilidad, productos y recomendaciones internacionales · pág. 13',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.11 Señale la fecha o periodo más reciente en que la información propuesta fue generada o actualizada:\n5.12 Indique las fechas en que la información propuesta estuvo a disposición anteriormente:\n                          Denominación                                   Fecha o periodo\n5.13 Liste los materiales o medios considerados para la divulgación de la información propuesta y el lugar donde se pueden consultar:\n                 Nombre de los materiales o medios                Lugar o sitio web de consulta\n5.14 ¿Aplica normas, estándares o recomendaciones de organismos nacionales o internacionales para la generación de la\n     información propuesta?\n     (Si selecciona la opción &quot;Sí&quot;, especifique el nombre de la norma, estándar o recomendación y el nombre del organismo que lo elaboró)\n      Sí           No  Limpiar</pre></div></section>',E'anexo',12,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Disponibilidad, productos y recomendaciones internacionales',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'969aa8cf-31f0-5cc6-8073-ee4683d09efa',E'Normatividad y metadatos · pág. 14',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.15 Señale las disposiciones normativas del SNIEG utilizadas para la generación de la información propuesta:\n                 Nombre de la disposición normativa                       Fecha de publicación\n 5.16 ¿Aplica la Norma Técnica para la elaboración de Metadatos Geográficos para la documentación de la información propuesta\n          Sí           No\n                      Limpiar      Si su respuesta es negativa, especifique por qué no la aplica\n 5.17 ¿Cuál es el estatus de inscripción de los conjuntos de datos y productos geográficos de la información propuesta en el\n      Registro Nacional de Información Geográfica (RNIG)?\n  Registrado\n  En proceso de registro\n  No registrado\n   Limpiar\n5.18 Indique las fases del proyecto geográfico para generar la información propuesta y el manual de procesos empleado:\n            Fases del proyecto geográfico       Nombre del manual          Sitio donde puede consultarse *\n        * Anexar documento cuando no se pueda consultar</pre></div></section>',E'anexo',13,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Normatividad y metadatos',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'bee8936d-b1b1-5dfd-a3a7-b24023d5abcb',E'Formatos de recopilación y almacenamiento · pág. 15',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.19 Marque los formatos en que recopila y almacena la información propuesta:\n                                                   (Marque las opciones correspondientes)\n                                           Recopilación                       Almacenamiento\n        1. Impresos\n               1.1 Formatos / expedientes\n               1.2 Mapas\n               1.3 Fotos aéreas\n               1.4 Ortofotos\n               1.5 Imágenes\n        2. Archivos electrónicos\n               2.1 Vectoriales\n               2.2 Ráster\n               2.3 Alfanuméricos\n        3. Base de datos\n        4. Otros\n5.20 ¿Se recibe algún tipo de asistencia técnica o de capacitación de un organismo nacional o internacional que contribuya en el\n    proceso de generación de la información propuesta?\n                                          (Marque las opciones correspondientes)\n             Tipo de asistencia\n                                                       Si contesta Sí, especifique el organismo que proporciona la asistencia\n                       Sí\n       Apoyo técnico\n                       No\n                     Limpiar\n                       Sí\n        Capacitación\n        No\n                     Limpiar</pre></div></section>',E'anexo',14,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Formatos de recopilación y almacenamiento',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'fe9a2fd6-e209-560b-831e-35771e81f187',E'Catálogos y periodo disponible · pág. 16',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.21 Mencione los catálogos que se emplean en la generación de la información propuesta, así como el sitio donde pueden ser\n    consultados:\n                            Catálogo                              Sitio donde puede consultarse *\n        * Anexar documento cuando no se pueda consultar en un sitio web.\n                                6. FECHA O PERIODO DE INFORMACIÓN DISPONIBLE\n6.1 Anote la fecha o periodo a partir de la cual se considera que la información propuesta cumple con los criterios documentados en\n   este formato:\n                  Fecha o periodo</pre></div></section>',E'anexo',15,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Catálogos y periodo disponible',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'546e3192-f39b-5666-a5ab-650b747e2c8a',E'Observaciones · pág. 17',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                        Observaciones\n(Si se requiere, hacer las anotaciones que se consideren necesarias para la mejor comprensión de la información proporcionada en este formato)</pre></div></section>',E'anexo',16,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Observaciones',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'1d8ab467-a217-5bad-b026-7b4adcebe920',E'Persona responsable y entrega · pág. 18',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                Identificación de la persona que elaboró el formato\nPersona responsable de\n                           Nombre:\nproporcionar la información\nincluida en este formato:\n                           Apellidos:\n                           Puesto:\n                           Domicilio\n                           institucional:\n                           Teléfono\n                           institucional:\n                           Correo electrónico\n                           institucional:\nFecha de entrega del formato:\nFirma:\n(Rubricar cada una de las hojas y\nentregar formato protegido en\nmedio magnético o electrónico)</pre></div></section>',E'anexo',17,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Formato de propuesta geográfica',E'Persona responsable y entrega',E'73ae89a0-b87b-5b24-ae9e-7486666a7d8c') on conflict(id) do nothing;
insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values (E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57',E'Instructivo de llenado del Formato para la presentación de Propuestas de Información Geográfica de Interés Nacional',E'IFIIN-GEO',null,null,true,ARRAY[E'SNIEG',E'INEGI',E'Información de Interés Nacional',E'Propuestas geográficas',E'Formato',E'Instructivo']::text[],E'https://www.snieg.mx/Documentos/Normatividad/Formatos_reg/Instructivo_Formato_IIN_Geografica.pdf',E'manual') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'32023a96-32a2-58f2-9c6c-e96ecbcc2bdd',E'Introducción · pág. 2',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                               Introducción\nEl Instituto Nacional de Estadística y Geografía, como\norganismo responsable de normar y coordinar el Sistema\nNacional de Información Estadística y Geográfica, tiene\ncomo uno de sus objetivos realizar las acciones tendientes\na lograr que la Información de Interés Nacional se sujete a\nlos principios de accesibilidad, transparencia, objetividad e\nindependencia  a efecto de coadyuvar  al  desarrollo nacional.\nCon el objeto de establecer las bases de aplicación de los\ncriterios para la determinación de la Información estadística\ny geográfica que habrá de considerarse de Interés Nacional,\nla Junta de Gobierno aprobó las Reglas para la determinación\nde Información de Interés Nacional, publicadas en el Diario\nOficial de la Federación el 9 de abril de 2018.\nCon base en dichas Reglas, se pone a disposición el\npresente Instructivo de llenado del Formato para la\nPresentación de Propuestas de Información Geográfica de\nInterés Nacional.</pre></div></section>',E'anexo',1,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Introducción',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'3c18a206-bce5-54b0-9b9b-848c9d0fb180',E'Contenido · pág. 3',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                                         Contenido\n Introducción                                                      2\n I.  Objetivo y ámbito de aplicación                               4\n II.  Estructura del formato                                       4\nIII.  Instrucciones generales de llenado                           5\nIV.  Instrucciones por apartado                                    6\n V.  Glosario                                                    29\n Anexo I.\n Diagrama de flujo para la presentación de propuestas\n de Información de Interés Nacional      32</pre></div></section>',E'anexo',2,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Contenido',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'3e59cb54-9bbd-5790-a9d9-36dd863986bd',E'Objetivo, ámbito y estructura · pág. 4',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">       I. Objetivo y ámbito de aplicación\n            Objetivo\n            Describir las instrucciones para el llenado del Formato para la Presentación de Propuestas de\n            Información Geográfica de Interés Nacional.\n            Ámbito de aplicación\n            Corresponde a las Unidades del Estado del SNIEG, a través de los Comités Técnicos\n            Especializados, proponer al Comité Ejecutivo correspondiente la información que pueda ser\n            considerada para determinarse como Información de Interés Nacional, mediante el llenado del\n            Formato correspondiente.\n            Asimismo, en caso de que algún representante de los sectores social, privado o académico\n            tenga interés de presentar alguna propuesta, ésta deberá realizarse a través del Presidente del\n            Comité Técnico Especializado que atiende el tema relacionado con la información de dicha\n            propuesta.\n       II. Estructura del formato\n            1. Información propuesta y proponente.\n            2. Proyecto geográfico que genera la información e institución responsable.\n            3. Políticas públicas de alcance nacional.\n            4. Atención de emergencias o compromisos internacionales.\n            5. Metodología para la generación de la información propuesta.\n            6. Fecha o periodo de información disponible.\n            Observaciones.\n            Identificación de la persona que elaboró el formato.\n            De acuerdo con la estructura del formato a continuación se presenta la relación conceptual de las\n            preguntas con respecto a los criterios para determinar la IIN (LSNIEG. Art. 78) y atributos y\n            principios rectores (LSNIEG. Art. 3) del SNIEG:\n               ESTRUCTURA CONCEPTUAL DEL FORMATO PARA LA PRESENTACIÓN DE PROPUESTAS DE INFORMACIÓN\n                                          GEOGRÁFICA DE INTERÉS NACIONAL\n      CRITERIOS    VARIABLES PARA   VARIABLES DE PRINCIPIOS RECTORES DEL SNIEG  VARIABLES DE ATRIBUTOS DE LA INFORMACIÓN DEL SNIEG\n    DETERMINACIÓN  DETERMINACIÓN\n      DE LA IIN       DE IIN  Accesibilidad  Objetividad  Transparencia  Independencia  Calidad  Pertinencia  Veracidad  Oportunidad\nProponente          1.1\n1. Información propuesta  1.2, 1.3, 1.4,                                        1.2, 1.3, 1.4,\n (Temática)         1.5.                                                        1.5\n2. Políticas públicas de\n                    3.1, 3.2                                                    3.1, 3.2\n alcance nacional\n3. Regularidad y periodicidad  5.9, 5.10, 6.1\n                                                                      2.1, 2.2, 2.3,      2.1, 2.2,\n4. Metodología      2.1, 2.2, 2.3,       5.14, 5.15,                            5.1, 5.2, 5.3,     5.7, 5.8,\n                               5.7, 5.13            5.7, 6.1  5.6     5.14, 5.15,         2.3, 5.17,\n científicamente sustentada  5.1 - 5.20  5.16, 5.19                             5.4, 5.5           5.11, 5.12\n                                                                      5.16, 5.17          5.18\nAtención de compromisos\n                    4.1, 4.2, 4.3,\ninternacionales o emergencias                                                   4.1, 4.3\n                    4.4\npor desastres naturales</pre></div></section>',E'anexo',3,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Objetivo, ámbito y estructura',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'0a56ba80-23c3-5f45-9e02-5ad354d23792',E'Instrucciones generales · pág. 5',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">III. Instrucciones generales de llenado\n      Antes de iniciar el llenado del formato, es necesario tener presente las siguientes\n      consideraciones:\n      a.  Conocimiento de las Reglas para la determinación de la Información de Interés Nacional.\n         (Disponibles en:\n         http://www.snieg.mx/DocumentacionPortal/Normatividad/vigente/Reglas_Determinacion_Informacion_Interes_Nacion\n         al.pdf).\n      b. Para el adecuado llenado del Formato y la documentación de soporte que lo acompañan, las\n         Unidades del Estado contarán con la asesoría del Secretario Técnico del CTE en el cual se\n         prepara la propuesta.\n      c.  Algunas preguntas tienen opciones de respuesta y admiten sólo la selección de una; en tanto\n         que otras pueden ser respondidas seleccionando más de una opción de respuesta.\n      d.  Utilizar mayúsculas y minúsculas, y no usar abreviaturas.\n      e.  Tener disponible documentación de utilidad para dar respuesta a las preguntas, como:\n         • Programa de trabajo de la Unidad del Estado.\n         • Documentos conceptuales, de sustentación y/o de presentación de la información\n           geográfica propuesta a caracterizar.\n         • Documentos metodológicos utilizados en la ejecución del proyecto.\n         • Productos geográficos.\n        • Instructivo de llenado del Formato.\n        ·  Fichas técnicas inscritas en el Registro Nacional de Información Geográfica (RNIG) de los\n           conjuntos de datos y productos geográficos de la información propuesta.\n      f. Es importante considerar que la documentación referida en los apartados 5 y 6 del formato\n       deberá estar disponible en forma digital para que una vez que la información propuesta sea\n       aprobada como de Interés Nacional se pueda proporcionar para su integración y administración\n       en el Acervo de Información de Interés Nacional, de acuerdo con lo dispuesto en las respectivas\n       Reglas, las cuales se pueden consultar en: SNIEG &gt; La Normatividad del SNIEG &gt; Sistema de\n       Compilación Normativa &gt; Normatividad vigente, en: http://www.snieg.mx/#top.</pre></div></section>',E'anexo',4,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Instrucciones generales',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'7c7c3b8d-d934-5113-92bd-dd853928c6f4',E'Información propuesta y proponente · pág. 6',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">IV. Instrucciones por apartado\n 1. INFORMACIÓN PROPUESTA Y PROPONENTE\n    1.1  Nombre de la Unidad del Estado y del Comité Técnico Especializado que propone la\n        información para ser designada como Información de Interés Nacional:\n    Anotar el nombre de la Unidad del Estado y el del Comité Técnico Especializado que somete la\n    propuesta para su evaluación al Comité Ejecutivo correspondiente.\n    1.2 Denominación de la información propuesta:\n    Indicar el nombre con el que se va a conocer a la información propuesta.\n    1.3 Objetivo de la información propuesta:\n    Establecer el propósito y alcance de aplicación de la información propuesta.</pre></div></section>',E'anexo',5,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Información propuesta y proponente',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'8650fdee-a142-5a4f-ac45-9e2f3e623718',E'Grupos de datos y usuarios · pág. 7',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">1.4  De los siguientes grupos de datos, marque las opciones que relacionen a la información\n    propuesta como de Interés Nacional. Si selecciona “Otro”, especifique el grupo:\nSeleccionar en el cuadro el grupo de datos para el cual estará dirigida la propuesta de información.\nEn caso de que las opciones no encuadren con la información propuesta, señalar el numeral 8\n(Otro) y especificar, en el espacio que se activará, el grupo de datos a que hace referencia la\ninformación.\n1.5 Principales usuarios identificados de la información propuesta:\nSeñalar los principales usuarios que se beneficiarán con la información propuesta.</pre></div></section>',E'anexo',6,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Grupos de datos y usuarios',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'fc1f440e-a7b0-5567-a047-cf8181c9cd3d',E'Proyecto geográfico y responsables · pág. 8',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">2. PROYECTO GEOGRÁFICO QUE GENERA LA INFORMACIÓN E\n    INSTITUCIÓN RESPONSABLE\n2.1 Descripción del proyecto geográfico:\nAnotar la descripción del proyecto que genera la información propuesta.\n2.2 Fases que comprende el proyecto geográfico:\nAnotar cada una de las fases del proyecto geográfico que da origen a la información propuesta.\n2.3 Unidad responsable de efectuar las fases del proyecto geográfico:\nAnotar el nombre de la Unidad del Estado a cargo del desarrollo de cada una de las fases del\nproyecto según corresponda.</pre></div></section>',E'anexo',7,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Proyecto geográfico y responsables',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'fda6bc33-d457-57ab-9e4d-8b01d94b74eb',E'Políticas públicas · pág. 9',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">3.  POLÍTICAS PÚBLICAS DE ALCANCE NACIONAL\n En este apartado se deberá señalar si la información geográfica propuesta es de utilidad porque\n así lo determina algún ordenamiento legal y/o por ser necesaria para la formulación y evaluación\n de las políticas definidas en el Plan Nacional de Desarrollo o Planes Estatales de Desarrollo vigentes,\n así como en los Programas Sectoriales, Regionales o Especiales, además de identificar los objetivos,\n metas e indicadores específicos relacionados con el uso de la información.\n 3.1 La información geográfica propuesta se utiliza para:\n Anotar si la información propuesta se utilizará para diseñar nuevas políticas públicas en determinada\n materia; o si la información será de utilidad para el seguimiento a políticas públicas ya en operación.</pre></div></section>',E'anexo',8,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Políticas públicas',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'bb70c14a-bdaa-5ff4-b2df-a82d7e4a9893',E'Fundamento legal · pág. 10',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">3.2 La información geográfica propuesta debe generarse porque lo estipula:\n    3.2.1 Ley aplicable\n         En caso de seleccionar la opción “Sí”, deberá anotar el nombre de la ley, título, capítulo,\n         sección, artículo, fracción, párrafo, fecha de última publicación y observaciones donde\n         se estipula generar la información propuesta. En caso de que no exista un mandato de ley\n         que mandate generar la información propuesta, seleccionar “No”.\n    3.2.2 Otro ordenamiento jurídico\n         Marcar la opción “Sí” cuando la propuesta de información es en cumplimiento a otro\n         ordenamiento jurídico y anotar cuál es el ordenamiento que se estaría cumplimentando.\n         De no existir otro ordenamiento que mandate generar la información propuesta, marcar\n         la opción “No”.</pre></div></section>',E'anexo',9,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Fundamento legal',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'e5b7b195-9054-5af2-89df-b0ab15d01993',E'Plan Nacional de Desarrollo · pág. 11',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">3.2.3 El Plan Nacional de Desarrollo:\n     Seleccionar la opción “Sí” cuando la información propuesta servirá para monitorear alguno\n     de los objetivos del Plan Nacional de Desarrollo (PND) además de señalar a cuál eje rector\n     del PND se estaría atendiendo; así como los objetivos y estrategias relacionadas. En el\n     caso de que la información propuesta no se relacione con el PND, seleccionar la opción\n     “No”.</pre></div></section>',E'anexo',10,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Plan Nacional de Desarrollo',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'df3ae541-1e24-596a-8380-2969b67bc7fd',E'Programas sectoriales, regionales o especiales · pág. 12',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">3.2.4 Programa sectorial, regional o especial:\n     En caso de que la información derive de un programa sectorial, regional o especial,\n     seleccione la opción “Sí” y especifique en los recuadros que se activarán cuál es, así como\n     los objetivos, metas e indicadores relacionados.\n     Anexar al formato, el archivo o dirección electrónica donde se puede consultar el programa\n     que se menciona.\n     Si la información no derive de un programa sectorial, regional o especial, seleccione la\n     opción “No”.</pre></div></section>',E'anexo',11,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Programas sectoriales, regionales o especiales',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'1c2dcdb8-d8fd-5371-a50f-2fcc84336f08',E'Atención de emergencias · pág. 13',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">4. ATENCIÓN DE EMERGENCIAS O COMPROMISOS\n    INTERNACIONALES\n4.1 ¿Cuáles de los siguientes organismos han declarado de utilidad la información propuesta para\n     prevenir o atender desastres naturales?\nSeleccionar entre las casillas señaladas la opción correspondiente. En caso de ser uno distinto a\nlos establecidos, seleccionar la opción “Otros” y especificar cuál(es).\n4.2   Anote la disposición y el lugar donde puede consultarse el fundamento donde se declare que\n     la información propuesta se utiliza para prevenir o atender desastres naturales:\n  Si en 4.1 seleccionó las opciones 1 a 3, en la columna “Disposición” se deberá indicar el documento\n  legal y en la columna “lugar donde se puede consultar” el sitio o lugar donde se localiza el\n  documento. Si en 4.1 seleccionó la opción 4, deje en blanco esta pregunta.</pre></div></section>',E'anexo',12,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Atención de emergencias',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'd55c5a63-1e39-5dc2-baf7-2bf3ab120188',E'Compromisos internacionales · pág. 14',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">4.3  ¿La información propuesta se utiliza para atender acuerdos, tratados o compromisos\n     establecidos a nivel internacional?\nMarcar la opción “Si” cuando la información propuesta como de Interés Nacional se enmarca en un\nordenamiento de corte internacional y anote el nombre del ordenamiento, así como el país u\norganismo correspondiente. En caso contrario seleccione la opción “No” y deje en blanco la pregunta\n4.4.\n4.4 ¿El compromiso internacional ha sido suscrito por el Presidente de la República y aprobado\n     por el Senado?\nSi la respuesta 4.3 fue afirmativa, seleccionar la opción “Si” cuando el compromiso internacional esté\nfirmado y aprobado por el Poder Ejecutivo y el Legislativo respectivamente, anexar el documento\nque sustente el compromiso y las observaciones pertinentes en el recuadro. En caso que el\ncompromiso internacional no esté firmado y aprobado por el Poder Ejecutivo y el Legislativo\nrespectivamente, seleccionar la opción “No”.</pre></div></section>',E'anexo',13,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Compromisos internacionales',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'99a533bc-8ed0-5653-8640-6e009b4ae920',E'Cobertura y referencia temporal · pág. 15',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5. METODOLOGÍA PARA LA GENERACIÓN DE LA INFORMACIÓN\n    PROPUESTA\n  5.1 ¿Cuál es la cobertura geográfica de la información propuesta?\n  Indicar en el recuadro las áreas geográficas (nacional, estatal, municipal, regional, local u otra) que\n  cubre la información propuesta.\n  Cuando no se cubran áreas específicas es necesario mencionar las razones por las que el\n  proyecto no cubrió el total del área geográfica bajo estudio. Por ejemplo, en un proyecto cuya\n  cobertura es por localidad y en el que sólo se consideran las localidades mayores a 2500 habitantes.\n  5.2 ¿Cuál es la referencia temporal de la información propuesta conforme a las fases del proyecto\n       geográfico?\n  En la columna “Fase” anotar el nombre de cada una de las fases que componen el proyecto\n  geográfico y en la columna “Referencia Temporal” anotar el periodo para el cual los datos se\n  consideran representativos para cada fase. La cantidad de fases de este apartado debe\n  corresponder con las definidas en el apartado 2.2.</pre></div></section>',E'anexo',14,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Cobertura y referencia temporal',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'5af1265e-81b6-5b52-840b-18c1c21fee1e',E'Temas, objetos espaciales y unidad mínima · pág. 16',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.3 Temas y objetos espaciales de la información propuesta:\nEn la columna “Tema” anotar el nombre de cada tema del proyecto geográfico y en la columna\n“Objetos espaciales” anotar el nombre de los objetos espaciales por tema.\n5.4 ¿Cuál es la unidad mínima de la información propuesta?\nIndicar la superficie que debe tener el objeto espacial de la información propuesta\nEjemplo:\n    Superficie\n   mínima para\n  áreas agrícolas                                                          Superficie\n                                                                          mínima para\n     25 ha.                                                                áreas de\n                                                                           vegetación\n                                                                            50 ha.\n                             San José de Gracia, Aguascalientes, Ags.</pre></div></section>',E'anexo',15,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Temas, objetos espaciales y unidad mínima',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'aaa4b61a-b988-5715-ab45-a0b1d73e3af6',E'Geodesia, proyección, escala y regularidad · pág. 17',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans"> 5.5  Para la información propuesta indique:\n Indicar según corresponda: el marco de referencia geodésico, la proyección, la escala, la exactitud\n y para el caso de información ráster, también la resolución.\n 5.6 ¿La Unidad Responsable de la generación de la información propuesta cuenta con un\n      fundamento legal que le permita decidir con independencia sobre las metodologías y normas\n      empleadas, al margen de influencias políticas y otras influencias externas?\n Indicar si la Unidad responsable de generar la información propuesta como de Interés Nacional\n realiza sus actividades y toma de decisiones libre de presiones de grupos de interés o influencias\n externas.\n 5.7 ¿Se dan a conocer a los usuarios de la información propuesta los metadatos, metodologías,\n      así como las fechas de publicación de la misma?\n Indicar si se da a conocer al usuario en general la metodología del proyecto, los metadatos de la\n información propuesta y las fechas de publicación.\n 5.8 Indicar las acciones que se emplean para generar o actualizar la información propuesta de\n     manera regular:\n A manera de ejemplo, y no limitativo, las acciones que pueden listarse en este apartado son:\n Administrativas, Logística y Capacitación:\n- Asegurar la disponibilidad de un equipo de especialistas en el tema; podría requerir la contratación\n y/o recuperación de la plantilla laboral por renuncias, cambios de adscripción, retiros, etc.\n- Preparar un programa presupuestal, considerando las necesidades de salidas a campo, reuniones\n técnicas, materiales, etc.\n- En caso de tener contratados nuevos especialistas, preparar, programar y realizar los cursos\n necesarios para la capacitación y especialización.\n- Actualizar manuales de Procedimientos y Procesos.\n- Verificar, y en su caso realizar los trámites para que los especialistas dispongan del equipo\n necesario de gabinete y campo, software, etc.\n- Desarrollar programas de actividades a lo largo del ciclo de actualización; programa de verificación\n de campo, de obtención y preparación de insumos, procedimientos de entrega y recepción de\n materiales, validación, realización de reuniones técnicas, capacitación, asignación de cargas y\n funciones de trabajo (especialistas, supervisores).</pre></div></section>',E'anexo',16,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Geodesia, proyección, escala y regularidad',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'12942168-6816-5349-9400-9d3ed49b3c11',E'Actualización y periodicidad · pág. 18',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans"> Técnicas y normativas:\n- Desarrollar / actualizar la metodología de actualización. Implica también actualización de\n conocimientos en el tema.\n- Seleccionar, obtener y distribuir información bibliográfica de soporte, así como información geográfica\n auxiliar.\n- Actualizar diccionarios de datos (si es pertinente).\n- Seleccionar y asegurar la disponibilidad de imágenes de satélite en la fecha o año de referencia para\n la información a actualizar; lo que implica disponer de cobertura nacional y que tengan las\n características deseadas; resolución, calidad geométrica, bandas espectrales requeridas, etc.\n 5.9 ¿Cuál es la periodicidad con la que se genera o actualiza la información propuesta?\n En la columna “Fase” anotar el nombre de cada una de las fases de la información propuesta y en la\n columna “Frecuencia” la periodicidad con la que se genera o actualiza según corresponda.\n 5.10 Indique la frecuencia con la que se hace pública la información propuesta:\n Marcar la opción que corresponda según la periodicidad con la que se hace pública la información,\n si elige la opción “Otra”, especificar en el recuadro correspondiente.</pre></div></section>',E'anexo',17,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Actualización y periodicidad',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'97fe8298-11c9-5ea7-9595-9c285659c4c8',E'Disponibilidad y recomendaciones internacionales · pág. 19',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.11 Señale la fecha o periodo más reciente en que la información propuesta fue generada o\n     actualizada:\n5.12 Indique las fechas en que la información propuesta estuvo a disposición anteriormente:\nEn la columna “Denominación” indicar el nombre con el que se puso a disposición la información\nanteriormente y en la columna “Fecha o Periodo” indique la fecha o periodo en que fue dispuesta\nsegún denominación.\n5.13 Liste los materiales o medios considerados para la divulgación de la información propuesta y\n     el lugar donde se pueden consultar:\nIndicar el nombre de los materiales considerados para la divulgación de la información propuesta y\nel lugar o sitio web donde puedan ser consultados.</pre></div></section>',E'anexo',18,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Disponibilidad y recomendaciones internacionales',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'f48972bb-91e2-5d99-ac8a-11610aa9f23b',E'Recomendaciones y normas · pág. 20',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.14 ¿Aplica normas, estándares o recomendaciones de organismos nacionales o internacionales\n     para la generación de la información propuesta?\nSi selecciona la opción “Sí”, indicar el nombre de la norma, estándar o recomendación y el nombre\ndel organismo responsable de su elaboración.\n5.15  Señale las disposiciones normativas del SNIEG utilizadas para la generación de la\n    información propuesta:\nEn la primera columna indicar el nombre de la disposición normativa y en la segunda columna la\nfecha de la publicación según corresponda.</pre></div></section>',E'anexo',19,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Recomendaciones y normas',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'461c399b-a8f4-51fc-bd20-7a09fe154514',E'Metadatos y documentación · pág. 21',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.16  ¿Aplica la Norma Técnica para la elaboración de Metadatos Geográficos para la\n    documentación de la información propuesta?\nMarcar Si, cuando la Norma citada es aplicada, en caso que No, especificar el motivo por el cual\nno se aplica dicha Norma.\n5.17 ¿Cuál es el estatus de inscripción de los conjuntos de datos y productos geográficos de la\n    información propuesta en el Registro Nacional de Información Geográfica (RNIG)?\nSeleccione la opción correspondiente según los conjuntos de datos y productos geográficos de la\ninformación propuesta estén registrados, en proceso de registro o no registrados en el Registro\nNacional de Información Geográfica (RNIG).\nSi selecciona la opción Registrado, se desplegará un recuadro para que especifique la fecha de\nactualización más reciente; si selecciona la opción En proceso de registro, se desplegará un recuadro\npara que especifique la fecha probable de conclusión del registro; si selecciona la opción No\nregistrado, se desplegará un recuadro en el que deberá especificar el motivo del no registro y la\nfecha probable de registro. En este caso deberá ponerse en contacto con el INEGI a la cuenta de\ncorreo atención.rnig@snieg.mx para iniciar la inscripción de los conjuntos de datos y productos\ngeográficos en el RNIG.</pre></div></section>',E'anexo',20,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Metadatos y documentación',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'036d0563-7514-540e-8a29-a120ec9fd8e8',E'Diagrama de procesos · pág. 22',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.18 Indique las fases del proyecto geográfico para generar la información propuesta y el manual\n     de procesos empleado:\nEn la primera columna listar las fases de desarrollo del proyecto geográfico para obtener la\ninformación propuesta, en la segunda columna especifique el(os) nombre(s) del(os) manual(es) de\nproceso(s) empleado(s) en cada fase y en la tercera columna el sitio web donde puedan ser\nconsultados, cuando no sea posible su consulta, anexar el documento. La cantidad de fases de este\napartado debe corresponder con las definidas en el apartado 2.2.</pre></div></section>',E'anexo',21,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Diagrama de procesos',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'80f9c460-5afd-5ae5-bac9-430a999f1fc3',E'Formatos de recopilación y almacenamiento · pág. 23',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.19 Marque los formatos en que recopila y almacena la información propuesta.\nIndicar los formatos en los que se recopila y almacena la información propuesta. Considerar que la\nrecopilación son todas aquellas actividades orientadas a captar, extraer y reunir datos geográficos\npara organizarlos con base en criterios previamente establecidos y el almacenamiento, aquellas que\npermiten registrar, reunir o guardar física o virtualmente datos en dispositivos internos o externos,\nque contribuyen a su conservación. En caso de seleccionar la opción “Otros” adicionalmente deberá\nespecificar el formato en cuestión.</pre></div></section>',E'anexo',22,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Formatos de recopilación y almacenamiento',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'1575fc64-07a8-5cb9-a9e2-a79f6efea66f',E'Asistencia técnica y capacitación · pág. 24',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.20 ¿Se recibe algún tipo de asistencia técnica o de capacitación de un organismo nacional o\n     internacional que contribuya en el proceso de generación de la información propuesta?\nSeleccionar la opción “Si”, en caso de contar con apoyo técnico de parte de un organismo nacional\no internacional, y/o de capacitación, y especificar qué tipo de apoyo y/o capacitación así como el\norganismo que lo brinda.</pre></div></section>',E'anexo',23,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Asistencia técnica y capacitación',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'40356488-c990-5b2c-9171-ddcc840f165f',E'Catálogos · pág. 25',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">5.21 Mencione los catálogos que se emplean en la generación de la información propuesta, así\n     como el sitio donde pueden ser consultados:\nAnotar el nombre de los catálogos involucrados para la generación de la información propuesta,\nasí como el sitio para su consulta.</pre></div></section>',E'anexo',24,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Catálogos',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'84a5b982-9caa-525b-9d8c-bab25911f9fc',E'Periodo disponible · pág. 26',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans"> 6.  FECHA O PERIODO DE INFORMACIÓN DISPONIBLE\n6.1 Anote la fecha o periodo a partir de la cual se considera que la información propuesta cumple con\nlos criterios documentados en este formato:\nSeñale la fecha o período de generación a partir de la cual la información generada por el proyecto\ngeográfico cumple con los criterios para ser propuesta como Información de Interés Nacional.</pre></div></section>',E'anexo',25,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Periodo disponible',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'03a343cc-1e66-50c4-94c2-71cec0805fd1',E'Observaciones · pág. 27',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">                                     Observaciones\n  (Si se requiere, hacer las anotaciones que se consideren necesarias para la mejor comprensión de la información proporcionada en este formato)\nUtilice este espacio si considera que es conveniente hacer anotaciones sobre la información que\nincluyó en el Formato que requiera especificaciones adicionales para una mejor comprensión de la\nmisma.</pre></div></section>',E'anexo',26,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Observaciones',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'2e9c8bd3-f870-5608-8789-56af66c4c144',E'Persona responsable y entrega · pág. 28',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans"> Identificación de la persona que elaboró el formato\nAnotar los datos solicitados de la persona que llenó el formato con la propuesta de Información de Interés\nNacional, con la cual se pueda establecer comunicación para aclarar dudas sobre la información\nproporcionada.\nAnotar la fecha de entrega del formato de presentación de la propuesta, la cual deberá coincidir con la\nfecha de envío a la instancia correspondiente.\nEl formato deberá incluir la firma de la persona que lo llenó, así como la rúbrica en cada una de las\nhojas que lo componen.\nLa entrega del formato deberá ser protegido en medio magnético o electrónico.</pre></div></section>',E'anexo',27,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Persona responsable y entrega',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'b9d71775-954c-5e66-8952-255cb0e8468e',E'Glosario · 1 · pág. 29',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">V. Glosario.\nAccesibilidad: conjunto de condiciones bajo las cuales los usuarios pueden obtener Información\n    Estadística y/o Geográfica.\nAcervo de Información o Acervo: conjunto de Información de Interés Nacional que ya ha sido difundida\n    por el Servicio Público de Información, así como sus metadatos, metodologías y/o especificaciones\n    concretas de la aplicación de las metodologías utilizadas en su generación.\nActividades Estadísticas y Geográficas o Actividades: relativas al diseño, captación, producción,\n    actualización, organización, procesamiento, integración, compilación, publicación, divulgación y\n    conservación de la Información de Interés Nacional.\nCalidad: grado en que un conjunto de características inherentes a los procesos y productos cumple con\n    determinados atributos.\nCobertura geográfica: espacio territorial al que está referida la información que se produce o integra\n    por el proyecto geográfico.\nComité Ejecutivo o CE: son órganos colegiados de participación que contribuyen a la coordinación\n    interinstitucional y a la puesta en marcha de las políticas que se definan respecto a la realización de\n    las Actividades Estadísticas y Geográficas del Sistema.\nComité Técnico Especializado o CTE: las instancias colegiadas de participación y consulta creadas\n    por acuerdo de la Junta de Gobierno, e integradas por representantes de las Unidades del Estado y\n    del Instituto.\nConfidencialidad: condición que asegura la privacidad de los informantes, dado que los datos\n    individuales obtenidos para ser procesados, integrados, analizados y difundidos, de personas físicas\n    o morales, solamente deben ser utilizados para fines estadísticos.\nGrupos de datos geográficos: marco de referencia geodésico; límites costeros, internacionales,\n    estatales y municipales; datos de relieve continental, insular y submarino; datos catastrales,\n    topográficos, de recursos naturales y clima, así como nombres geográficos.\nReferencia temporal: fecha o periodo al cual corresponden los datos más recientes generados para\n    cada fase del proyecto geográfico.\n    Clasificación que se le da en función del cubrimiento de vuelos.\nDato: el valor que una variable estadística o un objeto espacial geográfico toma en una unidad de\n    observación.\nEscala: relación que existe entre una distancia medida en un mapa y la distancia correspondiente en\n    el terreno.\nEstructura ráster: estructura digital de datos definida por una cuadrícula distribuida de forma regular\n    conformada por píxeles que contienen un valor de atributo particular en cada uno de ellos.\nExactitud: grado de cercanía de una cantidad estimada, tal como una coordenada horizontal o una\n    altura, con respecto a su valor verdadero.\nIndependencia: característica de las Unidades del Estado para producir y difundir información libre de\n    presiones de grupos de interés.\nInformación de Interés Nacional: la señalada en el artículo 59 de la Ley del Sistema Nacional de</pre></div></section>',E'anexo',28,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Glosario · 1',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'243d9cac-cb79-5174-9870-5e39700dbd07',E'Glosario · 2 · pág. 30',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">    Información Estadística y Geográfica, así como aquella que la Junta de Gobierno determine como\n    tal de acuerdo con lo establecido en los artículos 77, fracción II y 78 de dicha Ley.\nInformación propuesta: grupo de datos y productos derivados de ellos, definido mediante la\n    especificación de temas, subtemas, universos, cobertura espacial y temporal, periodicidad,\n    escalas, proyecciones, variables u objetos espaciales, clasificaciones y parámetros que sean\n    resultado de un operativo estadístico o geográfico determinado y puesto a consideración de la\n    Junta de Gobierno para ser valorado y, en su caso, determinado como Información de Interés\n    Nacional.\nJunta de Gobierno o JG: Junta de Gobierno del INEGI.\nMarco de Referencia Geodésico: es la materialización del Sistema Geodésico Nacional.\nMetadatos: los datos estructurados que describen las características de contenido, calidad, condición,\n    acceso y distribución de la información geográfica.\nMetodología: procedimiento que ordena y articula el conjunto particular de actividades necesarias para\n    producir información estadística y geográfica.\nMetodología científicamente sustentada: aquella que responde a la aplicación del método científico\n    que busca establecer la explicación de un fenómeno, de la que resulte una definición congruente\n    con los datos de la observación. También se incluyen en esta categoría a las mejores prácticas y\n    recomendaciones internacionales en la materia.\nObjetividad: atributo que asegura que las Unidades del Estado generan y difunden información que\n    refleje la realidad, tan fielmente como sea posible.\nObjeto Espacial: abstracción a partir de un elemento del espacio geográfico. Puede corresponder con\n    elementos de la naturaleza, con elementos producto de la mano del hombre o con abstracciones\n    numéricas derivadas de las dos anteriores. Su característica intrínseca es la referencia espacial en\n    dos o tres dimensiones expresada en coordenadas geográficas o cartesianas.\nOperativo geográfico: procedimiento y esquema técnico para las actividades de recolección\n    (recopilación) y/o actualización de datos geográficos precisos sobre la organización del espacio\n    terrestre, sus características y las relaciones jerárquicas que se establecen entre los elementos\n    constitutivos del espacio representados de manera digital o analógica por medio de cartas, planos,\n    croquis y catálogos.\nOportunidad: tiempo transcurrido entre que la Información está disponible para los usuarios y el hecho\n    o fenómeno que describe.\nPertinencia: grado en que la Información Estadística y Geográfica responde a los requerimientos de los\n    usuarios.\nProyección: conjunto de operaciones matemáticas definidas para representar la superficie de la Tierra\n    sobre un plano.\nResolución horizontal: medidas que se tienen en el plano horizontal (x-y) de la unidad mínima de\n    información establecida para los datos con estructura ráster.\nResolución vertical: medida de la distancia mínima que se tiene en el plano vertical de un punto entre\n    una superficie de referencia a lo largo de la dirección perpendicular a dicha superficie y el punto.\nSistema Geodésico Nacional: es el conjunto de Especificaciones Técnicas de la Norma del Sistema\n    Geodésico Nacional.</pre></div></section>',E'anexo',29,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Glosario · 2',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'cae318d2-dc96-57d8-a8ce-01a727ba62cf',E'Glosario · 3 · pág. 31',E'<section><p><strong>Nota de consulta:</strong> Transcripción para consulta y búsqueda. Las casillas, tablas y disposición visual se consultan en el PDF original sincronizado.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Proponente: Unidad del Estado que presenta una propuesta de información para que sea determinada\n    como de Interés Nacional de acuerdo con lo previsto en el artículo 78, de la LSNIEG.\nReglas: Reglas para la determinación de Información de Interés Nacional.\nSistema Nacional de Información Estadística y Geográfica o SNIEG: conjunto de Unidades del Estado\n    organizadas a través de los Subsistemas y que son coordinadas por el INEGI y articuladas mediante\n    la Red Nacional de Información, con el propósito de producir y difundir la Información de Interés\n    Nacional.\nSubsistema Nacional de Información: componente del Sistema Nacional de Información Estadística y\n    Geográfica, cuyo objetivo es producir, integrar, difundir y conservar Información de una determinada\n    clase o respecto de temas específicos.\nTemas o Grupos de Datos: los considerados en la fracción I, del artículo 78 de la Ley y adicionados por\n    la Junta de Gobierno de conformidad con el citado numeral y mediante el procedimiento establecido\n    en estas Reglas.\nTransparencia: condición en la que todas las políticas y prácticas que envuelven una Actividad Estadística\n    o Geográfica se dan a conocer a los usuarios.\nUnidades del Estado o UE: a las áreas administrativas que cuentan con atribuciones para desarrollar\n    Actividades Estadísticas y Geográficas o que cuentan con registros administrativos que permitan\n    obtener Información de Interés Nacional de:\n    a) Las dependencias y entidades de la Administración Pública Federal, incluyendo a las de la\n       Presidencia de la República y de la Procuraduría General de la República;\n    b) Los Poderes Legislativo y Judicial de la Federación;\n    c) Las entidades federativas, los municipios y las demarcaciones territoriales de la Ciudad de México;\n    d) Los organismos constitucionales autónomos, y\n    e) Los tribunales administrativos federales.\n    Cuando el Instituto genere Información se considerará como Unidad del Estado\nUnidad mínima de la información: está relacionada con la escala y se refiere a la superficie que\n    como mínimo debe tener un objeto espacial; por ejemplo un área de agricultura o de un determinado\n    tipo o condición de vegetación, para ser representado en un conjunto de datos como un polígono.\n    En el caso de objetos espaciales de importancia ecológica de forma alargada y que no cumplen\n    con la superficie mínima para ser representados como áreas, se considera una longitud mínima\n    para ser representados como líneas.\nVector: cualquier línea que tiene un origen y un destino, una orientación y una determinada magnitud.\nVeracidad: grado de aproximación de los cálculos o estimaciones a los valores exactos que la\nInformación Estadística o Geográfica está destinada a representar.</pre></div></section>',E'anexo',30,E'Instrumento de apoyo · artículo 11 de las Reglas de determinación de IIN',E'Instructivo de llenado',E'Glosario · 3',E'6a5c31f6-3882-5eec-ab36-0ba3a20fae57') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'cfc60768-a4d1-5256-968b-594a261e7483',E'Anexo I · Diagrama de flujo · pág. 32',E'<section><p><strong>Nota de consulta:</strong> Anexo I: el diagrama de flujo y sus conexiones se consultan en el PDF original sincronizado. El texto siguiente es únicamente la transcripción de sus rótulos.</p><div class="overflow-x-auto"><pre class="whitespace-pre font-sans">Anexo I. Diagrama de flujo para la presentación de propuestas de Información de Interés Nacional\n     UNIDAD DEL ESTADO           COMITÉ TÉCNICO             COMITÉ EJECUTIVO             JUNTA DE GOBIERNO       SERVIDORES PÚBLICOS DEL\n        PROPONENTE               ESPECIALIZADO                                                                       INEGI Y EXPERTOS\n         Inicio  Inicio\n            Inicio\n   Presenta propuesta de IIN a  El Presidente recibe propuesta  El Presidente recibe informe  Recibe y valora propuesta\n    Presidente de CTE con la  para su revisión y análisis con\n   documentación y formatos       el ST del CTE\n                                                                                                                    La JG invita a servidores\n                                                                                                             Si    públicos del INEGI y expertos\n                                                              El ST del CE elabora        ¿Se requiere apoyo        en el tema para analizar la\n                                                            dictamen de cumplimiento de     para valorar?         propuesta y elaboran éstos un\n                           Si     ¿Se requieren             criterios 6 a 9 de las Reglas\n             ST solicita                                                                                             informe para que la JG\n          adecuaciones a UEP      adecuaciones?\n                                                                                             No\n                                   No                                          No\n                                                                                                              Si\n                                                                                           ¿Satisface criterios\n                                                              ¿Cumple criterios?\n                                                                                          para determinar IIN?\n                                El ST elabora informe\n                                                                  Sí                        No\n                                                            El Presidente convoca a        ¿Procede solicitar  Si\n                               El Presidente entrega al                                  revisión de criterios no\n                                                           sesión al pleno del CE para\n                                Presidente del CE\n                                                                su validación                satisfechos?\n                            correspondiente, informe con la\n                               resolución del análisis y                                      No\n                              formato y documentación\n                                    soporte.               Validada la propuesta por el\n                                                            pleno del CE, el Presidente  Emite Acuerdo de no procedencia de\n                                                           del mismo la envía y expone  IIN y el Presidente del CE notifica la\n                                                                  a la JG.               decisión a la Proponente\n                                                           El Presidente del CE solicita  Solic